user_prompt:
method rolling_max(numbers: seq<int>) returns (result: seq<int>)
    requires |numbers| > 0
    ensures |result| == |numbers|
    ensures forall i :: 0 <= i < |result| ==> result[i] == max(numbers[0..i + 1])
{
    var maxVal := numbers[0];
    var res := new int[|numbers|];

    // Initialize the first element
    res[0] := maxVal;

    // Compute rolling max
    var i := 1;
    while i < |numbers|
        invariant 0 <= i <= |numbers|
        invariant |res| == |numbers|
        invariant forall j :: 0 <= j < i ==> res[j] == max(numbers[0..j + 1])
    {
        if numbers[i] > maxVal {
            maxVal := numbers[i];
        }
        res[i] := maxVal;
        i := i + 1;
    }

    result := res;
}

problem_data.canonical_solution:
running_max = None
result = []

for n in numbers:
    if running_max is None:
        running_max = n
    else:
        running_max = max(running_max, n)

    result.append(running_max)

return result

